-- Kort #253, Verify (femma sju punkt 1, Bengts ja 26/9, DECISIONS #373): samma censurmätning som 25/9 (censur-grind-a-2026-09-25.sql),
-- men över FÖRSTA HELA DYGNET efter att den levande ingesten började spara varma, torra avläsningar (deploy 25/9 07:20Z, PR #567):
-- 25/9 07:30Z–26/9 07:30Z. Kortets gräns: under 5 % saknade grannplatser i kalla halvtimmar. Plus arkivets tillväxt per dygn, före
-- och efter ändringen — samma 24 h-fönster ett dygn tidigare. Bara antal, ingen felkvot. Körs med dbknapp: en sats per rad.
WITH gr AS (SELECT a.station_id AS s, b.station_id AS n FROM weather_latest a CROSS JOIN LATERAL (SELECT b.station_id FROM weather_latest b WHERE b.station_id <> a.station_id AND b.geom IS NOT NULL AND ST_DWithin(a.geom::geography, b.geom::geography, 50000) ORDER BY a.geom <-> b.geom LIMIT 5) b WHERE a.geom IS NOT NULL), mal AS (SELECT station_id, floor(extract(epoch FROM sample_time) / 1800)::bigint AS b, max(surface_temp_c) AS yta FROM weather_observations WHERE sample_time >= '2026-09-25T07:30:00Z' AND sample_time < '2026-09-26T07:30:00Z' AND surface_temp_c <= 5 AND air_temp_c IS NOT NULL AND surface_temp_c >= air_temp_c - 12 AND (air_temp_c < 10 OR air_temp_c - surface_temp_c < 8) GROUP BY 1, 2), par AS (SELECT m.station_id, m.b, m.yta, EXISTS (SELECT 1 FROM weather_observations x WHERE x.station_id = g.n AND x.sample_time >= to_timestamp(m.b * 1800) AND x.sample_time < to_timestamp((m.b + 1) * 1800) AND x.surface_temp_c IS NOT NULL AND x.air_temp_c IS NOT NULL AND x.surface_temp_c >= x.air_temp_c - 12) AS med FROM mal m JOIN gr g ON g.s = m.station_id) SELECT 'kalla (yta <= 5)' AS urval, count(DISTINCT (station_id, b)) AS malhalvtimmar, count(*) AS grannplatser, count(*) FILTER (WHERE med) AS med_rad, count(*) FILTER (WHERE NOT med) AS saknas, round(100.0 * count(*) FILTER (WHERE NOT med) / nullif(count(*), 0), 1) AS andel_saknas_pct FROM par UNION ALL SELECT 'frysnära (yta <= 1)', count(DISTINCT (station_id, b)), count(*), count(*) FILTER (WHERE med), count(*) FILTER (WHERE NOT med), round(100.0 * count(*) FILTER (WHERE NOT med) / nullif(count(*), 0), 1) FROM par WHERE yta <= 1
SELECT 'före (24/9 07:30Z–25/9 07:30Z)' AS dygn, count(*) AS rader, count(DISTINCT station_id) AS stationer FROM weather_observations WHERE sample_time >= '2026-09-24T07:30:00Z' AND sample_time < '2026-09-25T07:30:00Z' UNION ALL SELECT 'efter (25/9 07:30Z–26/9 07:30Z)', count(*), count(DISTINCT station_id) FROM weather_observations WHERE sample_time >= '2026-09-25T07:30:00Z' AND sample_time < '2026-09-26T07:30:00Z'
SELECT pg_size_pretty(pg_total_relation_size('weather_observations')) AS vaderarkivet, pg_size_pretty(pg_database_size(current_database())) AS databasen
